/**
 * Cuts the README's play button: the game's own proclamation banner.
 *
 * The line at the top of both READMEs — the one thing on either page anybody has to press — was a
 * shields.io badge: a remote PNG, generated by somebody else's server, set in somebody else's
 * Verdana, fetched through GitHub's image proxy on every view. It reads fine and it is three
 * things this repo tries not to be: dependent on a service, unstyled by the game, and impossible
 * to look at before it ships.
 *
 * The first cut here kept shields' two-block shape and only changed who printed it, which was
 * answered by pointing at a screenshot of the game: *why are you not using the style in here?*
 * Fair. The game already has a button that means "something is being announced" — the relief
 * proclamation that crosses the sky when help reaches a fight (`scenes/conquest/battle/relief.ts`)
 * — and every part of it is a decision this project already made: a swallow tail cut into both
 * ends, gold rules with the Ngọc Lũ drum's sawtooth inside them, a seal at the head, a title in
 * Source Serif and a quieter line under it.
 *
 * So the README's button is that banner. The proportions and the numbers below are read off the
 * renderer, not invented: tail 16 of a 56-tall band, rules 4 in from the edge, sawtooth 3.5 tall
 * starting 8 in, the seal 46 from the left end.
 *
 * Rendered in Chromium at 3x and displayed at its CSS width, because a README is read on a retina
 * laptop as often as not and a 1x button is the one blurred thing on the page.
 *
 * Usage: node scripts/build-play-badge.mjs [--out public/share]
 */
import { chromium } from 'playwright';
import { mkdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';

const arg = (flag, fallback) => {
  const at = process.argv.indexOf(flag);
  return at >= 0 ? process.argv[at + 1] : fallback;
};

const OUT = arg('--out', 'public/share');
const SCALE = 3;

// From src/ui/ink/palette.ts, which is where the banner reads them too. Derive, do not invent.
const SON = '#b33a26';        // cinnabar — the banner's cloth
const SON_DEEP = '#8e2c1c';   // the same pigment pulled heavier, for the tail's shadow side
const HOE = '#c08a2e';        // hoa hòe — the rules and the sawtooth
const HOE_PALE = '#dcbe7e';   // the title's ink
const DIEP_HI = '#f3ecd8';    // điệp — the line under it
const MUC = '#2a2118';        // mực — the contour

/**
 * The faces, inlined.
 *
 * The page is rendered from a string with no base URL, so `url(SourceSerif4-700-latin.woff2)`
 * resolves to nothing and the button comes out in whatever Chromium falls back to — which is not
 * the face the game is set in, and on another machine is not even the same face twice. Base64
 * costs a large string and buys a button that is identical wherever it is cut.
 *
 * Both families, 700 only: everything on this banner is bold.
 */
function faces() {
  const files = [
    ['Source Serif 4', 'SourceSerif4-700'],
    ['Be Vietnam Pro', 'BeVietnamPro-700'],
  ];
  // No `unicode-range`: with one weight per family there is nothing to choose between, and the
  // browser walks the faces in order until it finds the glyph. Vietnamese last means `Ơ` and `Ế`
  // are found there rather than dropped.
  return files.flatMap(([family, stem]) => ['latin', 'latin-ext', 'vietnamese'].map((subset) => {
    const data = readFileSync(`public/fonts/${stem}-${subset}.woff2`).toString('base64');
    return `@font-face{font-family:'${family}';font-weight:700;font-style:normal;`
      + `src:url(data:font/woff2;base64,${data}) format('woff2');}`;
  })).join('\n');
}

/**
 * One banner. `title` is the proclamation, `note` the line under it — the same two registers the
 * fight screen's ribbon carries, and the same reason: the first says what this is, the second what
 * it costs. Case is applied in CSS so the Vietnamese keeps its diacritics.
 */
const BANNERS = [
  { file: 'play-badge.png', title: 'Play the full game', note: 'free · no ads · in your browser' },
  { file: 'play-badge-vi.png', title: 'Chơi trọn game', note: 'miễn phí · không quảng cáo · ngay trên trình duyệt' },
];

/** The banner's own geometry, in the renderer's units. */
const H = 84;
const TAIL = 24;

const html = (banner) => `<!doctype html><meta charset="utf-8"><style>
${faces()}
*{margin:0;padding:0;box-sizing:border-box}
body{background:transparent}

.wrap{display:inline-block;position:relative;padding:0 0 5px 0;}

/* The cloth, and the swallow tail: a V cut into each end, which is the whole reason the shape
   reads as a banner rather than as a bar. The clip-path below is the same six points the
   renderer's polygon has. */
.band{
  position:relative;
  height:${H}px;
  padding:0 ${TAIL + 30}px 0 ${TAIL + 74}px;
  display:flex;flex-direction:column;align-items:center;justify-content:center;
  background:linear-gradient(180deg, ${SON} 0%, ${SON} 62%, ${SON_DEEP} 100%);
  clip-path:polygon(0 0, 100% 0, calc(100% - ${TAIL}px) 50%, 100% 100%, 0 100%, ${TAIL}px 50%);
}

/* The two gold rules, and the drum's sawtooth inside them.
   Crossed repeating gradients were the first try and they print XXXXX: two opposed diagonals meet
   in the middle of every cell, which is a lattice, not a row of teeth. An SVG pattern of one
   stroked peak, tiled in user space, is the renderer's own sawtoothBand — a line, then triangles
   standing on it — and it tiles to any width the words happen to need. */
.rule{position:absolute;left:${TAIL - 6}px;right:${TAIL - 6}px;height:10px;}
.rule.top{top:6px}
.rule.bottom{bottom:6px}
.rule svg{display:block;width:100%;height:10px}

.title{
  font-family:'Source Serif 4',Georgia,serif;font-weight:700;
  font-size:27px;line-height:1;letter-spacing:.045em;text-transform:uppercase;
  color:${HOE_PALE};
  text-shadow:0 1px 0 rgba(42,33,24,.45);
}
.note{
  font-family:'Be Vietnam Pro',sans-serif;font-weight:700;
  font-size:13px;line-height:1;letter-spacing:.02em;margin-top:8px;
  color:${DIEP_HI};opacity:.96;
}

/* The seal at the head, where the fight screen's banner stamps the house: a disc seated in ink,
   ringed in gold, with the play mark cut out of it. 46 from the end, clear of the tail's notch. */
.seal{
  position:absolute;left:${TAIL + 12}px;top:50%;transform:translateY(-50%);
  width:44px;height:44px;border-radius:50%;
  background:${SON_DEEP};
  border:2.5px solid ${HOE};
  box-shadow:0 0 0 3px rgba(42,33,24,.22);
  display:flex;align-items:center;justify-content:center;
}
/* Drawn, not typed: ▶ is a different shape in every fallback font and missing from some, and this
   is the one element that must not be left to the renderer. */
.play{width:0;height:0;margin-left:4px;border-left:16px solid ${HOE_PALE};border-top:10px solid transparent;border-bottom:10px solid transparent;}

/* No cast shadow. The renderer draws one because it sits on a picture of a battlefield; this one
   sits on a README, whose ground is white in one theme and near-black in the other, and a grey
   slab offset behind a transparent PNG reads as a printing fault in both. */
</style>
<div class="wrap" id="badge">
  <div class="band">
    <div class="rule top"><svg viewBox="0 0 100 10" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg">
      <defs><pattern id="sawtop" patternUnits="userSpaceOnUse" width="6" height="10">
        <path d="M0 9 L3 3 L6 9" fill="none" stroke="${HOE}" stroke-width="1.1" opacity=".85"/>
      </pattern></defs>
      <rect x="0" y="0" width="100%" height="1.6" fill="${HOE}" opacity=".92"/>
      <rect x="0" y="0" width="100%" height="10" fill="url(#sawtop)"/>
    </svg></div>
    <div class="seal"><i class="play"></i></div>
    <div class="title">${banner.title}</div>
    <div class="note">${banner.note}</div>
    <div class="rule bottom"><svg viewBox="0 0 100 10" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg">
      <defs><pattern id="sawbot" patternUnits="userSpaceOnUse" width="6" height="10">
        <path d="M0 9 L3 3 L6 9" fill="none" stroke="${HOE}" stroke-width="1.1" opacity=".85"/>
      </pattern></defs>
      <rect x="0" y="0" width="100%" height="1.6" fill="${HOE}" opacity=".92"/>
      <rect x="0" y="0" width="100%" height="10" fill="url(#sawbot)"/>
    </svg></div>
  </div>
</div>`;

mkdirSync(OUT, { recursive: true });
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1100, height: 260 }, deviceScaleFactor: SCALE });
for (const banner of BANNERS) {
  await page.setContent(html(banner));
  await page.evaluate(() => document.fonts.ready);
  const shot = await page.locator('#badge').screenshot({ omitBackground: true });
  const path = `${OUT}/${banner.file}`;
  writeFileSync(path, shot);
  const box = await page.locator('#badge').boundingBox();
  console.log(`${path}  ${Math.round(box.width)}x${Math.round(box.height)} css  ·  ${(statSync(path).size / 1024).toFixed(1)} kB`);
}
await browser.close();
